// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UnfinishedBulkLoadTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void findsTheRunLeftBehindByAnInterruptedLoad() throws Exception {
		Path target = temporaryDirectory.resolve("store");
		interrupt(target);

		UnfinishedBulkLoad run = UnfinishedBulkLoad.find(target).orElseThrow();

		assertThat(run.target()).isEqualTo(target.toAbsolutePath().normalize());
		assertThat(run.controlDirectory()).isEqualTo(temporaryDirectory.resolve(".store.lmdb-bulk-load"));
		assertThat(run.currentPhase()).isEqualTo(BulkLoadPhase.STAGE_INPUTS);
		assertThat(run.completedPhases()).isEqualTo(1);
		assertThat(run.stagingComplete()).isFalse();
		assertThat(run.compression()).isEqualTo(BulkCompression.FASTEST);
	}

	/**
	 * Everything a caller needs to continue a run the way it started has to come back out of the workspace, because the
	 * person resuming it is generally not holding the command line that began it.
	 */
	@Test
	void reportsTheConfigurationAndInputsTheRunWasStartedWith() throws Exception {
		Path input = temporaryDirectory.resolve("input.nq");
		Files.writeString(input, "<urn:s> <urn:p> <urn:o> <urn:g> .\n");
		Path target = temporaryDirectory.resolve("store");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,posc");
		config.setInlineLiterals(false);
		AtomicInteger checks = new AtomicInteger();
		LmdbBulkLoader loader = LmdbBulkLoader.builder(target, config)
				.partitionCount(8)
				.workers(3)
				.cancellationSignal(() -> checks.incrementAndGet() >= 4)
				.build();
		assertThatThrownBy(
				() -> loader.load(List.of(new LmdbBulkLoader.PathInput(input, RDFFormat.NQUADS, "urn:test:"))))
						.isInstanceOf(CancellationException.class);

		UnfinishedBulkLoad run = UnfinishedBulkLoad.find(target).orElseThrow();

		BulkLoadSettings settings = run.settings().orElseThrow();
		assertThat(settings.tripleIndexes()).isEqualTo("spoc,ospc,posc");
		assertThat(settings.inlineLiterals()).isFalse();
		assertThat(settings.partitionCount()).isEqualTo(8);
		assertThat(settings.workers()).isEqualTo(3);
		assertThat(run.recordedInputs())
				.extracting(LmdbBulkLoader.PathInput::path)
				.containsExactly(input.toAbsolutePath().normalize());
		assertThat(run.resumableWithoutInputs())
				.as("a run that recorded its files can be finished without being handed them again")
				.isTrue();
	}

	@Test
	void reportsNoRunForAStoreThatWasNeverLoaded() throws Exception {
		assertThat(UnfinishedBulkLoad.find(temporaryDirectory.resolve("store"))).isEmpty();
	}

	@Test
	void discoversRunsWithinTheSearchDepthAndNotBeyondIt() throws Exception {
		Path near = Files.createDirectories(temporaryDirectory.resolve("near"));
		Path far = Files.createDirectories(temporaryDirectory.resolve("a/b/c/d"));
		interrupt(near.resolve("close"));
		interrupt(far.resolve("distant"));

		List<UnfinishedBulkLoad> shallow = UnfinishedBulkLoad.discover(temporaryDirectory, 2);
		List<UnfinishedBulkLoad> deep = UnfinishedBulkLoad.discover(temporaryDirectory,
				UnfinishedBulkLoad.DEFAULT_SCAN_DEPTH + 1);

		assertThat(shallow).extracting(UnfinishedBulkLoad::target)
				.containsExactly(near.resolve("close").toAbsolutePath().normalize());
		assertThat(deep).extracting(UnfinishedBulkLoad::target)
				.containsExactlyInAnyOrder(near.resolve("close").toAbsolutePath().normalize(),
						far.resolve("distant").toAbsolutePath().normalize());
	}

	/**
	 * The scan walks a working directory, so it has to step over the directories that dominate one: hidden trees like
	 * .git, and anything that merely carries the control directory's name without holding readable state.
	 */
	@Test
	void ignoresHiddenTreesAndDirectoriesThatOnlyLookLikeState() throws Exception {
		Path hidden = Files.createDirectories(temporaryDirectory.resolve(".git/objects"));
		interrupt(hidden.resolve("buried"));
		Files.createDirectories(temporaryDirectory.resolve(".impostor.lmdb-bulk-load"));
		Files.writeString(temporaryDirectory.resolve(".impostor.lmdb-bulk-load/state.properties"), "version=1\n");

		assertThat(UnfinishedBulkLoad.discover(temporaryDirectory, UnfinishedBulkLoad.DEFAULT_SCAN_DEPTH)).isEmpty();
	}

	@Test
	void discardingARunRemovesEverythingItWasHolding() throws Exception {
		Path target = temporaryDirectory.resolve("store");
		interrupt(target);
		UnfinishedBulkLoad run = UnfinishedBulkLoad.find(target).orElseThrow();
		Files.writeString(run.controlDirectory().resolve("statements.lz4"), "staged bytes");
		assertThat(run.workspaceBytes()).isPositive();

		run.discard();

		assertThat(run.controlDirectory()).doesNotExist();
		assertThat(UnfinishedBulkLoad.find(target)).isEmpty();
	}

	/**
	 * Leaves the state an interrupted load leaves: one phase done and the next one open.
	 */
	private static void interrupt(Path target) throws IOException {
		try (BulkLoadWorkspace workspace = BulkLoadWorkspace.open(target, null)) {
			workspace.startPhase(BulkLoadPhase.PREFLIGHT);
			workspace.completePhase(BulkLoadPhase.PREFLIGHT);
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
		}
	}
}
